update public.global_settings
set landing_content = jsonb_set(
  jsonb_set(
    coalesce(landing_content, '{}'::jsonb),
    '{features}',
    '{"title":"রিসেলিং শুরু করার জন্য যা যা দরকার — সবই এক প্যানেলে","subtitle":"প্রোডাক্ট সোর্সিং থেকে কুরিয়ার আর পেমেন্ট পর্যন্ত পুরো কাজ আমরা অটোমেট করে দিয়েছি, আপনি শুধু সেলে ফোকাস করুন।","items":[{"icon":"Boxes","title":"রেডি মাস্টার ক্যাটালগ","desc":"ভেরিফাইড প্রোডাক্ট, HD ছবি আর SEO রেডি ডেসক্রিপশন — এক ক্লিকে কপি করে নিজের স্টোরে লিস্ট করুন। কোনো স্টক কিনতে হবে না।"},{"icon":"Wallet","title":"নিজের প্রফিট নিজেই ঠিক করুন","desc":"প্রোডাক্ট প্রাইস, ডেলিভারি ও প্যাকেজিং কস্ট আগেই দেখানো থাকে — উপরে যত প্রফিট বসাবেন, পুরোটাই আপনার।"},{"icon":"Truck","title":"কুরিয়ার আমরা হ্যান্ডেল করি","desc":"Steadfast, Pathao ও CarryBee-তে বুকিং, প্যাকেজিং ও ডেলিভারি আমাদের টিম করে; আপনি প্যানেলে লাইভ পার্সেল স্ট্যাটাস দেখতে পাবেন।"},{"icon":"Globe","title":"নিজের ব্র্যান্ডেড স্টোর","desc":"কাস্টম ডোমেইন, লোগো, কালার, ফেভিকন ও থিম — কাস্টমার শুধু আপনার ব্র্যান্ড দেখবে, আমাদের কোনো তথ্য দেখবে না।"},{"icon":"Wallet","title":"COD ও অনলাইন পেমেন্ট","desc":"bKash, Nagad, Rocket সহ SSLCommerz ও EPS সাপোর্ট — ডেলিভারি হওয়ার পর প্রফিট ও কমিশন পেআউট রিপোর্টে পরিষ্কার দেখা যায়।"},{"icon":"Megaphone","title":"Facebook ও TikTok অ্যাডস ট্র্যাকিং","desc":"নিজের Pixel/CAPI আর TikTok Events API বসিয়ে দিন — প্রতিটি অ্যাড থেকে আসা অর্ডার নির্ভুলভাবে ট্র্যাক হবে।"},{"icon":"BarChart3","title":"লাইভ প্রফিট ড্যাশবোর্ড","desc":"সেল, ডেলিভারি রেট, রিটার্ন, লাইফটাইম রেভিনিউ, পেন্ডিং প্রফিট ও ডিউ পেমেন্ট — সব একসাথে রিয়েল-টাইমে।"},{"icon":"ShieldCheck","title":"সিকিউর ও প্রাইভেট ডেটা","desc":"প্রতিটি রিসেলারের অর্ডার ও কাস্টমার ডেটা সম্পূর্ণ আলাদা ও সুরক্ষিত — অন্য কেউ দেখতে পায় না।"},{"icon":"Sparkles","title":"টিম, লিডার ও কমিশন সিস্টেম","desc":"স্টাফ পারমিশন কন্ট্রোল আর লিডার রিসেলার স্ট্রাকচার — টিম বাড়িয়ে কমিশন ইনকাম বাড়ান।"}]}'::jsonb
  ),
  '{nav,features}', '"ফিচার"'::jsonb
)
where id = 1;